const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

if (require.main === module) {
  const port = process.env.PORT || 3000;

  app.listen(port, () => {
    console.log(`Server running on port ${port}`);
  });
}

module.exports = app;
```

## Summary

Hardcoded values to address:

| Value | Location | Recommendation |
|---|---|---|
| `3000` | `app.listen(3000)` | Use `process.env.PORT || 3000` |
| `'Server running on port 3000'` | log message | Use template string with configured port |
| User records | `/users` route | Use database/mock fixture; do not hardcode real data |
| Emails | `/users` route | Avoid exposing publicly; require auth if real data |

